/* Real QR modules for https://linejam.app/join?code=9AUK (level M, 29x29), precomputed once. */
window.PS_QR = { size: 29, path: "M0 0h7v1h-7zM8 0h3v1h-3zM12 0h4v1h-4zM17 0h4v1h-4zM22 0h7v1h-7zM0 1h1v1h-1zM6 1h1v1h-1zM8 1h1v1h-1zM11 1h1v1h-1zM13 1h1v1h-1zM16 1h2v1h-2zM22 1h1v1h-1zM28 1h1v1h-1zM0 2h1v1h-1zM2 2h3v1h-3zM6 2h1v1h-1zM9 2h3v1h-3zM16 2h1v1h-1zM18 2h1v1h-1zM20 2h1v1h-1zM22 2h1v1h-1zM24 2h3v1h-3zM28 2h1v1h-1zM0 3h1v1h-1zM2 3h3v1h-3zM6 3h1v1h-1zM8 3h3v1h-3zM14 3h2v1h-2zM17 3h1v1h-1zM19 3h1v1h-1zM22 3h1v1h-1zM24 3h3v1h-3zM28 3h1v1h-1zM0 4h1v1h-1zM2 4h3v1h-3zM6 4h1v1h-1zM9 4h1v1h-1zM11 4h2v1h-2zM14 4h1v1h-1zM16 4h1v1h-1zM19 4h1v1h-1zM22 4h1v1h-1zM24 4h3v1h-3zM28 4h1v1h-1zM0 5h1v1h-1zM6 5h1v1h-1zM10 5h1v1h-1zM13 5h1v1h-1zM15 5h5v1h-5zM22 5h1v1h-1zM28 5h1v1h-1zM0 6h7v1h-7zM8 6h1v1h-1zM10 6h1v1h-1zM12 6h1v1h-1zM14 6h1v1h-1zM16 6h1v1h-1zM18 6h1v1h-1zM20 6h1v1h-1zM22 6h7v1h-7zM8 7h3v1h-3zM12 7h1v1h-1zM15 7h3v1h-3zM19 7h2v1h-2zM0 8h1v1h-1zM2 8h2v1h-2zM5 8h3v1h-3zM9 8h5v1h-5zM15 8h3v1h-3zM22 8h1v1h-1zM25 8h1v1h-1zM27 8h2v1h-2zM0 9h2v1h-2zM3 9h1v1h-1zM7 9h2v1h-2zM10 9h1v1h-1zM12 9h4v1h-4zM17 9h1v1h-1zM19 9h6v1h-6zM28 9h1v1h-1zM1 10h2v1h-2zM4 10h3v1h-3zM8 10h3v1h-3zM12 10h2v1h-2zM16 10h1v1h-1zM18 10h1v1h-1zM22 10h1v1h-1zM26 10h2v1h-2zM0 11h1v1h-1zM4 11h1v1h-1zM7 11h2v1h-2zM15 11h2v1h-2zM18 11h1v1h-1zM20 11h1v1h-1zM23 11h1v1h-1zM28 11h1v1h-1zM0 12h1v1h-1zM3 12h2v1h-2zM6 12h1v1h-1zM10 12h2v1h-2zM14 12h1v1h-1zM17 12h1v1h-1zM19 12h1v1h-1zM25 12h2v1h-2zM1 13h1v1h-1zM3 13h3v1h-3zM7 13h1v1h-1zM9 13h1v1h-1zM14 13h1v1h-1zM16 13h2v1h-2zM19 13h2v1h-2zM22 13h1v1h-1zM26 13h3v1h-3zM5 14h3v1h-3zM9 14h5v1h-5zM17 14h1v1h-1zM19 14h1v1h-1zM22 14h1v1h-1zM24 14h1v1h-1zM26 14h3v1h-3zM0 15h1v1h-1zM2 15h1v1h-1zM4 15h1v1h-1zM9 15h1v1h-1zM11 15h1v1h-1zM14 15h3v1h-3zM23 15h1v1h-1zM27 15h1v1h-1zM1 16h1v1h-1zM3 16h2v1h-2zM6 16h1v1h-1zM10 16h1v1h-1zM14 16h1v1h-1zM16 16h1v1h-1zM18 16h1v1h-1zM21 16h1v1h-1zM23 16h3v1h-3zM27 16h1v1h-1zM1 17h2v1h-2zM4 17h1v1h-1zM7 17h6v1h-6zM14 17h1v1h-1zM17 17h1v1h-1zM20 17h1v1h-1zM23 17h1v1h-1zM25 17h3v1h-3zM0 18h1v1h-1zM4 18h1v1h-1zM6 18h1v1h-1zM9 18h1v1h-1zM11 18h7v1h-7zM22 18h3v1h-3zM26 18h1v1h-1zM2 19h2v1h-2zM5 19h1v1h-1zM7 19h4v1h-4zM12 19h3v1h-3zM17 19h2v1h-2zM20 19h2v1h-2zM23 19h2v1h-2zM26 19h1v1h-1zM1 20h1v1h-1zM4 20h1v1h-1zM6 20h3v1h-3zM11 20h1v1h-1zM13 20h2v1h-2zM16 20h11v1h-11zM8 21h1v1h-1zM12 21h1v1h-1zM15 21h2v1h-2zM18 21h3v1h-3zM24 21h5v1h-5zM0 22h7v1h-7zM8 22h1v1h-1zM10 22h1v1h-1zM14 22h1v1h-1zM16 22h5v1h-5zM22 22h1v1h-1zM24 22h2v1h-2zM27 22h1v1h-1zM0 23h1v1h-1zM6 23h1v1h-1zM8 23h1v1h-1zM10 23h2v1h-2zM13 23h2v1h-2zM16 23h1v1h-1zM20 23h1v1h-1zM24 23h2v1h-2zM0 24h1v1h-1zM2 24h3v1h-3zM6 24h1v1h-1zM16 24h2v1h-2zM20 24h5v1h-5zM26 24h2v1h-2zM0 25h1v1h-1zM2 25h3v1h-3zM6 25h1v1h-1zM8 25h1v1h-1zM10 25h3v1h-3zM15 25h1v1h-1zM17 25h1v1h-1zM19 25h2v1h-2zM23 25h3v1h-3zM28 25h1v1h-1zM0 26h1v1h-1zM2 26h3v1h-3zM6 26h1v1h-1zM8 26h1v1h-1zM10 26h5v1h-5zM18 26h2v1h-2zM23 26h1v1h-1zM26 26h1v1h-1zM28 26h1v1h-1zM0 27h1v1h-1zM6 27h1v1h-1zM9 27h2v1h-2zM14 27h3v1h-3zM20 27h1v1h-1zM22 27h1v1h-1zM24 27h2v1h-2zM27 27h1v1h-1zM0 28h7v1h-7zM8 28h1v1h-1zM10 28h1v1h-1zM12 28h5v1h-5zM19 28h2v1h-2zM22 28h1v1h-1zM24 28h1v1h-1zM27 28h1v1h-1z" };
/* Poem Shape: every screen shows where the group is in the 1-2-3-4-5-4-3-2-1 shape.
   One choreography: a bar fills when a line is accepted. Bars never move otherwise. */
(function () {
  const R = LJ.room;
  const WC = R.WORD_COUNTS;
  const P = R.byId;
  const reduceMotion = window.matchMedia('(prefers-reduced-motion: reduce)');

  /* Simulated server timings for the prototype. */
  const SUBMIT_PENDING_MS = 900;
  const OPEN_PENDING_MS = 600;
  const HOLD_AFTER_FILL_MS = 450;
  const FILL_MS = 300;

  const wait = (ms) => new Promise((resolve) => setTimeout(resolve, ms));
  const esc = (s) =>
    String(s).replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[c]);
  const firstName = (id) => P[id].name.split(' ')[0];
  const countWords = (text) => text.trim().split(/\s+/).filter(Boolean).length;
  const ORDINAL = ['first', 'second', 'third', 'fourth'];

  const ICON = {
    monitor: '<rect x="3" y="4" width="18" height="12" rx="2"/><path d="M8 20h8M12 16v4"/>',
    sound: '<path d="M11 5 6 9H3v6h3l5 4z"/><path d="M15.5 8.5a5 5 0 0 1 0 7M18.5 5.5a9 9 0 0 1 0 13"/>',
    dots: '<circle cx="5" cy="12" r="1.2" fill="currentColor"/><circle cx="12" cy="12" r="1.2" fill="currentColor"/><circle cx="19" cy="12" r="1.2" fill="currentColor"/>',
    copy: '<rect x="9" y="9" width="11" height="11" rx="2"/><path d="M5 15V6a2 2 0 0 1 2-2h9"/>',
    share: '<circle cx="18" cy="5" r="2.5"/><circle cx="6" cy="12" r="2.5"/><circle cx="18" cy="19" r="2.5"/><path d="m8.2 10.8 7.6-4.4M8.2 13.2l7.6 4.4"/>',
    check: '<path d="m5 12.5 4.5 4.5L19 7.5"/>',
    pen: '<path d="M4 20h4L19 9a2.8 2.8 0 0 0-4-4L4 16z"/>',
    moon: '<path d="M20 14.5A8 8 0 1 1 9.5 4a6.5 6.5 0 0 0 10.5 10.5z"/>',
    eye: '<path d="M2 12s3.5-7 10-7 10 7 10 7-3.5 7-10 7S2 12 2 12z"/><circle cx="12" cy="12" r="3"/>',
    voice: '<path d="M12 4a3 3 0 0 1 3 3v5a3 3 0 0 1-6 0V7a3 3 0 0 1 3-3z"/><path d="M6 11a6 6 0 0 0 12 0M12 17v3"/>',
  };
  const icon = (name, size = 20) =>
    `<svg class="ps-ico" viewBox="0 0 24 24" width="${size}" height="${size}" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false">${ICON[name]}</svg>`;

  const av = (id, size = 36) =>
    `<span class="ps-av" style="--av:${size}px">${LJ.avatar(P[id].avatar, { size: Math.round(size * 0.84) })}</span>`;

  /* ---------- Bars and silhouettes ---------- */

  function bar(words, state, attrs = '', style = '') {
    return `<span class="ps-bar" data-state="${state}" style="--w:${words};${style}" ${attrs}><span class="ps-fill"></span></span>`;
  }

  /* states: nine of 'filled' | 'dim' | 'now' | 'empty'. Pictorial only, so hidden from assistive tech. */
  function shape(states, cls) {
    return `<span class="ps-shape ${cls}" aria-hidden="true">${WC.map((w, i) => bar(w, states[i], `data-round="${i + 1}"`)).join('')}</span>`;
  }

  const statesFor = (filledCount, nowIndex = -1, fillState = 'filled') =>
    WC.map((_, i) => (i < filledCount ? fillState : i === nowIndex ? 'now' : 'empty'));

  /* The single choreography. Resolves when the bar is full. */
  function fillBar(el) {
    return new Promise((resolve) => {
      if (reduceMotion.matches) {
        el.dataset.state = 'filled';
        resolve();
        return;
      }
      el.classList.add('is-filling');
      el.getBoundingClientRect();
      el.dataset.state = 'filled';
      setTimeout(() => {
        el.classList.remove('is-filling');
        resolve();
      }, FILL_MS + 20);
    });
  }

  /* ---------- Chrome ---------- */

  const WORDMARK = '<span class="ps-wordmark">Linejam</span>';
  const CODE_ENTRY = `<button type="button" class="ps-code" aria-label="Invite friends to room ${R.codeDisplay}" aria-haspopup="dialog">${R.codeDisplay}</button>`;

  function frame(left, main) {
    return `<header class="ps-head">${left}<div class="ps-tools">
        <button type="button" class="ps-icon" aria-label="Appearance: System. Switch to Light.">${icon('monitor')}</button>
        <button type="button" class="ps-icon" aria-label="Sound is on. Turn sound off.">${icon('sound')}</button>
        <button type="button" class="ps-icon" aria-label="Room options" aria-haspopup="dialog">${icon('dots')}</button>
      </div></header>
      <p class="sr-only" role="status" aria-live="polite" data-live></p>
      ${main}`;
  }

  function announce(root, text) {
    const live = root.querySelector('[data-live]');
    live.textContent = '';
    requestAnimationFrame(() => {
      live.textContent = text;
    });
  }

  /* Replace the page under the header; the header and live region stay put. */
  function swapMain(root, html) {
    root.querySelector('main').outerHTML = html;
    return root.querySelector('main');
  }

  /* ---------- Lobby ---------- */

  function renderLobby(root) {
    const qr = window.PS_QR;
    const box = qr.size + 8;
    const seats = R.players
      .map(
        (p) => `<li class="ps-seat">
          ${shape(statesFor(0), 'ps-shape--seat')}
          <span class="ps-seat__who">${av(p.id, 40)}<span class="ps-seat__name">${esc(p.name)}${
            p.id === R.you ? '<span class="ps-seat__role">You, hosting</span>' : ''
          }</span></span>
        </li>`,
      )
      .join('');

    root.innerHTML = frame(
      WORDMARK,
      `<main class="ps-main ps-lobby">
        <h1 class="sr-only">Room lobby</h1>
        <section class="ps-invite" aria-label="Room invitation">
          <div class="ps-invite__text">
            <button type="button" class="ps-invite__code" data-copy aria-label="Copy room code ${R.codeDisplay}">
              <span>${R.codeDisplay}</span><span data-copy-icon>${icon('copy', 22)}</span>
            </button>
            <button type="button" class="ps-btn ps-btn--quiet ps-btn--fit">${icon('share')}<span>Share invite</span></button>
          </div>
          <svg class="ps-qr" viewBox="-4 -4 ${box} ${box}" role="img" aria-label="QR code for joining room ${R.codeDisplay}" shape-rendering="crispEdges">
            <rect x="-4" y="-4" width="${box}" height="${box}" fill="#ffffff"/><path d="${qr.path}" fill="#000000"/>
          </svg>
        </section>
        <section class="ps-poems" aria-labelledby="ps-poems-h">
          <div class="ps-row">
            <h2 id="ps-poems-h" class="ps-h2">Four players, four poems</h2>
            <p class="ps-meta">${R.players.length} of ${R.capacity}</p>
          </div>
          <p class="ps-lede">Everyone adds a line to every poem. At the end, each of you reads one aloud.</p>
          <ul class="ps-seats" aria-label="Players">${seats}</ul>
        </section>
        <div class="ps-actions">
          <button type="button" class="ps-btn ps-btn--primary">Start game</button>
        </div>
      </main>`,
    );

    const copy = root.querySelector('[data-copy]');
    copy.addEventListener('click', () => {
      copy.classList.add('is-copied');
      copy.querySelector('[data-copy-icon]').innerHTML = icon('check', 22);
      copy.setAttribute('aria-label', `Room code ${R.codeDisplay} copied`);
      announce(root, 'Room code copied');
    });
  }

  /* ---------- Writing, round 5 ---------- */

  function renderWriting(root) {
    const round = 5;
    const a = R.assignments[round - 1];
    const target = a.target;
    const rail = WC.map((w, i) =>
      bar(w, i < round - 1 ? 'filled' : i === round - 1 ? 'now' : 'empty', `data-round="${i + 1}" aria-hidden="true"`, `grid-row:${i + 1}`),
    ).join('');

    root.innerHTML = frame(
      CODE_ENTRY,
      `<main class="ps-main ps-write">
        <div class="ps-spine">
          ${rail}
          <div class="ps-spine__round">
            <h1 class="ps-kicker">Round ${round} of 9</h1>
            <p class="ps-prompt">Five words. The widest line.</p>
          </div>
          <div class="ps-spine__received">
            <p class="ps-caption">The line before yours</p>
            <p class="ps-received">${esc(a.previousLine)}</p>
          </div>
          <div class="ps-spine__compose">
            <label class="sr-only" for="ps-line">Write your line for round ${round}. Target: ${target} words.</label>
            <textarea id="ps-line" class="ps-input" rows="2" autocomplete="off" autocapitalize="sentences" spellcheck="true" aria-describedby="ps-count"></textarea>
            <div class="ps-meter">
              <span class="ps-slots" aria-hidden="true"></span>
              <span id="ps-count" class="ps-count"></span>
            </div>
          </div>
          <div class="ps-spine__submit">
            <button type="button" class="ps-btn ps-btn--primary" data-submit disabled>Submit</button>
          </div>
        </div>
      </main>`,
    );

    const ta = root.querySelector('#ps-line');
    const slots = root.querySelector('.ps-slots');
    const countEl = root.querySelector('#ps-count');
    const btn = root.querySelector('[data-submit]');
    const bar5 = root.querySelector(`.ps-spine > .ps-bar[data-round="${round}"]`);
    let pending = false;
    let hintTimer = 0;

    ta.value = 'and nobody asked';

    function update() {
      const n = countWords(ta.value);
      const over = Math.max(0, n - target);
      let html = '';
      for (let i = 0; i < target; i++) html += `<span class="ps-slot${i < n ? ' is-filled' : ''}"></span>`;
      for (let i = 0; i < Math.min(over, 4); i++) html += '<span class="ps-slot is-over"></span>';
      slots.innerHTML = html;

      countEl.classList.toggle('is-exact', n === target);
      countEl.classList.toggle('is-over', over > 0);
      countEl.innerHTML =
        n === target
          ? `${icon('check', 16)}<span>${n} of ${target} words</span>`
          : over > 0
            ? `<span>${n} of ${target} words. Remove ${over}.</span>`
            : `<span>${n} of ${target} words</span>`;

      btn.disabled = n !== target;
      ta.setAttribute('aria-invalid', String(over > 0));

      clearTimeout(hintTimer);
      hintTimer = setTimeout(() => {
        if (pending) return;
        const diff = target - n;
        announce(
          root,
          n === target
            ? 'Ready to submit'
            : n === 0
              ? ''
              : `${diff > 0 ? 'Add' : 'Remove'} ${Math.abs(diff)} word${Math.abs(diff) === 1 ? '' : 's'}`,
        );
      }, 500);
    }

    async function submit() {
      if (pending || countWords(ta.value) !== target) return;
      pending = true;
      clearTimeout(hintTimer);
      ta.readOnly = true;
      btn.setAttribute('aria-disabled', 'true');
      btn.textContent = 'Tucking in…';
      announce(root, 'Tucking your line in');

      await wait(SUBMIT_PENDING_MS); /* simulated server acceptance */

      announce(root, 'Tucked into the poem.');
      await fillBar(bar5);
      await wait(HOLD_AFTER_FILL_MS);
      showWaiting(root, { fromWriting: true });
    }

    ta.addEventListener('input', update);
    ta.addEventListener('keydown', (event) => {
      if (event.key === 'Enter') event.preventDefault();
    });
    btn.addEventListener('click', submit);
    update();
  }

  /* ---------- Waiting after your round-5 line ---------- */

  const ROUND5 = [
    { poem: 1, writer: 'juniper', status: 'in' },
    { poem: 2, writer: 'wren', status: 'in' },
    { poem: 3, writer: 'basil', status: 'writing' },
    { poem: 4, writer: 'marguerite', status: 'away' },
  ];
  const STATUS = {
    in: { icon: 'check', text: 'Tucked in', cls: 'ps-status--in' },
    writing: { icon: 'pen', text: 'Writing', cls: '' },
    away: { icon: 'moon', text: 'Away', cls: '' },
    watching: { icon: 'eye', text: 'Watching. Plays next game.', cls: '' },
  };

  function statusHtml(key) {
    const s = STATUS[key];
    return `<span class="ps-status ${s.cls}" data-status>${icon(s.icon, 16)}<span>${s.text}</span></span>`;
  }

  function poemLabel(entry) {
    return `Poem ${entry.poem}, round 5 with ${firstName(entry.writer)}: ${entry.status === 'in' ? 'line tucked in' : 'line not in yet'}`;
  }

  function waitingMain() {
    const poems = ROUND5.map(
      (e) => `<li class="ps-group__poem" data-poem="${e.poem}">
        ${shape(statesFor(e.status === 'in' ? 5 : 4, 4), 'ps-shape--group')}
        ${av(e.writer, 30)}
        <span class="sr-only" data-poem-label>${poemLabel(e)}</span>
      </li>`,
    ).join('');

    const statusOf = Object.fromEntries(ROUND5.map((e) => [e.writer, e.status]));
    const people = [...R.players, R.lateJoiner]
      .map(
        (p) => `<li class="ps-person" data-id="${p.id}">
          ${av(p.id, 38)}
          <span class="ps-person__text">
            <span class="ps-person__name">${esc(p.name)}${p.id === R.you ? ' (you)' : ''}</span>
            ${statusHtml(p.spectator ? 'watching' : statusOf[p.id])}
          </span>
        </li>`,
      )
      .join('');

    return `<main class="ps-main ps-wait">
      <div class="ps-ack">
        <p class="ps-kicker">Round 5 of 9</p>
        <h1 class="ps-ack__title" tabindex="-1">Tucked into the poem.</h1>
        <p class="ps-ack__sub">Round 6 starts when every line is in.</p>
      </div>
      <section class="ps-group" aria-labelledby="ps-group-h">
        <h2 id="ps-group-h" class="ps-caption">The four poems</h2>
        <ul class="ps-group__list">${poems}</ul>
      </section>
      <section class="ps-roster" aria-labelledby="ps-roster-h">
        <h2 id="ps-roster-h" class="ps-caption">This round</h2>
        <ul class="ps-people">${people}</ul>
      </section>
    </main>`;
  }

  function showWaiting(root, { fromWriting }) {
    const main = swapMain(root, waitingMain());
    if (!fromWriting) return;
    main.querySelector('.ps-ack__title').focus();

    /* Later, Basil's line is accepted: the same fill, on the poem Basil holds. */
    setTimeout(async () => {
      if (!main.isConnected) return;
      const entry = ROUND5.find((e) => e.writer === 'basil');
      const poem = main.querySelector(`[data-poem="${entry.poem}"]`);
      main.querySelector('[data-id="basil"] [data-status]').outerHTML = statusHtml('in');
      poem.querySelector('[data-poem-label]').textContent = poemLabel({ ...entry, status: 'in' });
      announce(root, 'Basil tucked in a line.');
      await fillBar(poem.querySelector('.ps-bar[data-round="5"]'));
    }, 2600);
  }

  function renderWaiting(root) {
    root.innerHTML = frame(CODE_ENTRY, waitingMain());
  }

  /* ---------- Reading circle ---------- */

  const ORDER = [0, 1, 2, 3]; /* reading order follows poem numbers: Marguerite, Basil, Wren, Juniper */

  function circleMain(variant) {
    const litIndex = variant === 'yours' ? 3 : 0;
    const rows = ORDER.map((i, pos) => {
      const poem = R.poems[i];
      const reader = poem.reader;
      const mine = reader === R.you;
      const lit = pos === litIndex;
      const read = pos < litIndex;
      const name = `${esc(P[reader].name)}${mine ? ' (you)' : ''}`;

      let who;
      let status = '';
      let action = '';
      if (lit && mine) {
        who = `${av(reader, 36)}<span>Your turn to read</span>`;
        action = `<button type="button" class="ps-btn ps-btn--primary ps-turn__action" data-open="${i}" data-mode="reader"><span>Open Poem ${poem.number}</span></button>`;
      } else if (lit) {
        who = `${av(reader, 36)}<span>${esc(firstName(reader))} is reading</span>`;
        action = `<button type="button" class="ps-btn ps-btn--quiet ps-btn--fit ps-turn__action" data-open="${i}" data-mode="listener">${icon('eye', 18)}<span>Read along</span></button>`;
      } else {
        who = `${av(reader, 32)}<span>${name}</span>`;
        const text = read
          ? `${icon('check', 16)}<span>Read</span>`
          : mine
            ? `<span>You read ${ORDINAL[pos]}</span>`
            : pos === litIndex + 1
              ? '<span>Up next</span>'
              : `<span>Reads ${ORDINAL[pos]}</span>`;
        status = `<p class="ps-turn__status">${text}</p>`;
      }

      return `<li class="ps-turn${lit ? ' is-lit' : ''}"${lit ? ' aria-current="step"' : ''}>
        ${shape(statesFor(9, -1, lit ? 'filled' : 'dim'), 'ps-shape--turn')}
        <div class="ps-turn__body">
          <p class="ps-turn__poem">Poem ${poem.number}</p>
          <p class="ps-turn__who">${who}</p>
          ${status}${action}
        </div>
      </li>`;
    }).join('');

    return `<main class="ps-main ps-read">
      <h1 class="ps-h1" tabindex="-1">Reading circle</h1>
      <p class="ps-lede">One poem at a time, read aloud in this order.</p>
      <ol class="ps-circle">${rows}</ol>
    </main>`;
  }

  function renderCircle(root, variant) {
    root.innerHTML = frame(CODE_ENTRY, circleMain(variant));
    bindCircle(root, variant);
  }

  function bindCircle(root, variant) {
    const btn = root.querySelector('[data-open]');
    btn.addEventListener('click', async () => {
      if (btn.getAttribute('aria-disabled') === 'true') return;
      btn.setAttribute('aria-disabled', 'true');
      btn.querySelector('span').textContent = 'Opening…';
      announce(root, 'Opening the poem');
      await wait(OPEN_PENDING_MS); /* simulated server: the poem is revealed */
      openPoem(root, Number(btn.dataset.open), btn.dataset.mode, variant);
    });
  }

  /* ---------- Poem open ---------- */

  function poemMain(index, mode) {
    const poem = R.poems[index];
    const authors = [...new Set(poem.lines.map(([, id]) => id))];
    const lines = poem.lines
      .map(
        ([text, author], i) => `<li class="ps-line" data-author="${author}">
          ${bar(WC[i], 'filled', 'aria-hidden="true"')}
          <span class="ps-line__text">${esc(text)}<span class="sr-only">, by ${esc(firstName(author))}</span></span>
        </li>`,
      )
      .join('');
    const chips = authors
      .map(
        (id) => `<button type="button" class="ps-chip" aria-pressed="false" data-author="${id}">${av(id, 32)}<span>${esc(firstName(id))}${
          id === R.you ? ' (you)' : ''
        }</span></button>`,
      )
      .join('');
    const readerLine =
      poem.reader === R.you
        ? `${av(poem.reader, 32)}<span>You are reading</span>`
        : `${av(poem.reader, 32)}<span>${esc(firstName(poem.reader))} is reading</span>`;

    return `<main class="ps-main ps-poem">
      <article class="ps-page" aria-labelledby="ps-poem-h">
        <h1 id="ps-poem-h" class="ps-h1" tabindex="-1">Poem ${poem.number}</h1>
        <p class="ps-page__reader">${readerLine}</p>
        <ol class="ps-lines">${lines}</ol>
        <section class="ps-key" aria-labelledby="ps-key-h">
          <h2 id="ps-key-h" class="ps-caption">Lines by. Tap a name to see theirs.</h2>
          <div class="ps-key__list">${chips}</div>
        </section>
      </article>
      <div class="ps-actions">
        <button type="button" class="ps-btn ${mode === 'reader' ? 'ps-btn--primary' : 'ps-btn--quiet'}" data-back>${
          mode === 'reader' ? 'Done reading' : 'Back to the circle'
        }</button>
      </div>
    </main>`;
  }

  function bindPoem(root, onBack) {
    const main = root.querySelector('main');
    const chips = [...main.querySelectorAll('.ps-chip')];
    const lines = [...main.querySelectorAll('.ps-line')];
    chips.forEach((chip) =>
      chip.addEventListener('click', () => {
        const on = chip.getAttribute('aria-pressed') !== 'true';
        chips.forEach((c) => c.setAttribute('aria-pressed', String(on && c === chip)));
        lines.forEach((l) => l.classList.toggle('is-quiet', on && l.dataset.author !== chip.dataset.author));
      }),
    );
    main.querySelector('[data-back]').addEventListener('click', onBack);
  }

  function openPoem(root, index, mode, variant) {
    const main = swapMain(root, poemMain(index, mode));
    bindPoem(root, () => {
      swapMain(root, circleMain(variant));
      bindCircle(root, variant);
      root.querySelector('.ps-h1').focus();
    });
    announce(root, `Poem ${R.poems[index].number} is open`);
    main.querySelector('#ps-poem-h').focus();
    if (reduceMotion.matches) return;
    /* Empty margin first, then all nine bars fill together as the whole poem appears. */
    main.classList.add('is-opening');
    main.getBoundingClientRect();
    requestAnimationFrame(() => main.classList.add('is-open'));
  }

  function renderPoemOpen(root) {
    root.innerHTML = frame(CODE_ENTRY, poemMain(0, 'listener'));
    bindPoem(root, () => renderCircle(root, 'turn'));
  }

  LJ.mount({
    title: 'Poem Shape',
    stance:
      'The 1-2-3-4-5-4-3-2-1 shape is the game\u2019s map. Every screen shows where the group is in the shape, so the rhythm of the game is visible without words. One motion: a bar fills when a line is accepted.',
    screens: [
      { id: 'lobby-host', label: 'Host lobby', render: renderLobby },
      { id: 'writing', label: 'Writing, round 5', render: renderWriting },
      { id: 'waiting', label: 'Waiting after your line', render: renderWaiting },
      { id: 'reading-turn', label: 'Reading circle, Marguerite reads', render: (root) => renderCircle(root, 'turn') },
      { id: 'poem-open', label: 'Poem 1 open', render: renderPoemOpen },
      { id: 'x-your-turn', label: 'Reading circle, your turn', render: (root) => renderCircle(root, 'yours') },
    ],
  });
})();
